import{z as p,x as B,o as t,c as A,q as n,j as o,D as i,d as r,s as l,S as E,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Splitwise","description":"","frontmatter":{"title":"Splitwise","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/splitwise.md","filePath":"llm/splitwise.md","lastUpdated":1791413859000}'),d={name:"llm/splitwise.md"};function m(h,e,P,D,S,c){const s=B("Mermaid");return t(),A("div",null,[e[2]||(e[2]=n('<h1 id="splitwise" tabindex="-1">Splitwise <a class="header-anchor" href="#splitwise" aria-label="Permalink to &quot;Splitwise&quot;">​</a></h1><div class="epigraph"><p>Prompt 阶段吃算力，generation 阶段吃带宽且往往喂不饱最新 GPU；按阶段拆池，才能把新卡留给前填、把功耗与成本留给生成。</p><footer>—— Patel et al., Splitwise: Efficient Generative LLM Inference Using Phase Splitting, ISCA 2024</footer></div><p>Patel、Choukse、Zhang、Shah、Goiri、Maleki、Bianchini 来自微软 Azure 一线，把生成式 LLM 推理写成一篇<strong>阶段表征 + 集群功耗</strong>的论文，venue 是 ISCA 2024（arXiv:2311.18677）。观察与 DistServe 同源：一次请求的 prompt 计算密集，generation 内存密集。差别在问题提法。DistServe 问的是同构集群上如何让 TTFT 与 TPOT 同时达标；Splitwise 问的是云上如何按阶段选机器代数、如何在功耗帽与美元预算里提高吞吐。它可以做同构拆分，也可以做异构：P 池用高算力卡，D 池用更便宜或更低功耗的卡。另设 mixed 池在突发时两阶段都能接，避免硬隔离导致一侧空、一侧炸。概念对照见 <a href="/llm/pd-disaggregation">PD 分离</a>；本篇钉 Splitwise 自己的池子、调度与数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>云厂商同时面对三张账单：GPU 资本、机柜功耗、用户 SLO。最新一代卡的峰值 FLOPs 对 prompt 有用，对 generation 常常浪费——逐步解码吃的是 HBM 带宽与 KV 容量，算术强度随 batch 涨得慢。若整条请求都钉在同一代旗舰卡上，生成阶段相当于用最贵的 SM 去等内存。反过来，若整条请求都放在上一代或更低功耗的卡上，长提示的 TTFT 会先爆。</p><p>Colocate 还有一条隐成本：为了同时伺候两阶段，机器必须按「更苛刻的那一侧」超配。prompt 突发时 generation 被拖慢，generation 占满显存时 prompt 排不上。功耗帽是硬约束：同一机柜里两阶段抢电，调度器没有「把电从生成挪给前填」的旋钮，因为它们绑在同一块板上。</p><h3 id="阶段表征先于调度" tabindex="-1">阶段表征先于调度 <a class="header-anchor" href="#阶段表征先于调度" aria-label="Permalink to &quot;阶段表征先于调度&quot;">​</a></h3><p>Splitwise 先把一次前向量成可测量的特征：算术强度、KV 增量、PCIe / NVLink 流量、功耗曲线。prompt 随序列长度二次涨计算、一次写出 KV；generation 每步计算几乎常数，读的 KV 线性涨。这个表征说明：最优硬件可以按阶段选，而不必按模型选。同一 70B，prompt 想要 Tensor Core 与高功耗帽，generation 想要容量与带宽、可以接受更低的 FLOPs。没有这条表征，异构拆分就是拍脑袋换卡。</p><p><span class="marginnote">数字实例：70B 模型 FP16 权重约 140 GB。生成一个 token 的计算量约 \\(2\\times 70\\mathrm{G}=140\\) GFLOPs，在 1 PFLOPS 的卡上理论只要约 0.14 ms；但把 140 GB 权重从 HBM 过一遍，按 3.3 TB/s 就要约 42 ms——差三百倍，这就是「生成阶段在等内存」的量账。</span></p><p><span class="marginnote">异构在这篇里是 GPU 代数与功耗档，不是「P 用 CPU、D 用 GPU」。生成阶段仍然要跑完整模型，只是用更贴合内存墙的机器。把 Splitwise 写成任意降级设备，会在不能放下权重的机器上失败。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>请求在 prompt 机器上算完提示、写出 KV 与首 token，再把状态经集群高速背板发给 generation 机器，继续连续批解码。调度分两层。集群级决定请求进哪类机器、是否走 mixed 池；机器级做批处理与本地排队。状态移动走 GPU 互连与优化过的网络库，而不是绕道主机内存再上普通以太网——除非实现有意降级。</p><p>同构拆分已经能消除阶段干扰。异构拆分再加一条：新卡集中在 P 池，D 池用上一代或同代但功耗帽更低的机器。Mixed 池是突发阀：暂时允许某台机器两阶段都做，避免「P 池空转、D 池炸队列」或反过来。传输量为零的请求（两阶段留在 mixed 同一台）给出「分离税」的下界，也是对照实验里必须保留的一档。</p><p><span class="marginnote">「分离税」翻译一下：请求从 P 机搬到 D 机要付的路费——KV 缓存跨机拷贝、首 token 多一跳转发。两阶段留在同一台的零传输请求就是这笔税的下界，拿它当对照组，才能量出拆分到底亏掉多少。</span></p><h3 id="功耗与成本是一等约束" tabindex="-1">功耗与成本是一等约束 <a class="header-anchor" href="#功耗与成本是一等约束" aria-label="Permalink to &quot;功耗与成本是一等约束&quot;">​</a></h3><p>论文把集群功耗和美元成本写进主结果，而不只报 token/s。相对当时 colocate 设计，报告可达约 1.4 倍吞吐并降约 20% 成本，或在同样功耗与成本预算下约 2.35 倍吞吐。读这些数字时要带着「预算相同」：分离会多复制一份权重，若不把卡数与电费算进去，1.4× 没有意义。Azure 生产痕迹在问题设定里：机器异构、机柜电、突发流量，都不是实验室里的单机批处理。</p>',16)),(t(),o(E,null,{default:i(()=>[l(s,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20CL%5B%22%E9%9B%86%E7%BE%A4%E8%B0%83%E5%BA%A6%EF%BC%9AP%20%2F%20D%20%2F%20mixed%22%5D%0A%20%20CL%20--%3E%20P%5B%22Prompt%20%E6%B1%A0%EF%BC%9A%E9%AB%98%E7%AE%97%E5%8A%9B%E5%8D%A1%22%5D%0A%20%20CL%20--%3E%20M%5B%22Mixed%20%E6%B1%A0%EF%BC%9A%E7%AA%81%E5%8F%91%E6%97%B6%E4%B8%A4%E9%98%B6%E6%AE%B5%E9%83%BD%E8%83%BD%E6%8E%A5%22%5D%0A%20%20P%20--%3E%20TX%5B%22%E6%9C%BA%E9%97%B4%E4%BC%A0%E8%BE%93%20KV%22%5D%0A%20%20TX%20--%3E%20D%5B%22Generation%20%E6%B1%A0%EF%BC%9A%E5%AE%B9%E9%87%8F%E4%B8%8E%E5%8A%9F%E8%80%97%E6%A1%A3%22%5D%0A%20%20M%20--%3E%20OUT%5B%22%E6%B5%81%E5%BC%8F%E8%BE%93%E5%87%BA%22%5D%0A%20%20D%20--%3E%20OUT%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[a("span",{class:"marginnote"},"2.35× 是「同样功耗与成本预算」下的吞吐，1.4× 是「降成本约 20%」时的吞吐。两套数字对应两种运营目标，不要合成「Splitwise 恒定两倍」。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"机制是让硬件屋顶线与阶段屋顶线对齐。Prompt 要的是 FLOPs，generation 要的是带宽与 KV 槽；拆开之后，各自的 batch、功耗帽、甚至机器代数都可以固定。Mixed 池承认真实到达过程不是稳态：硬隔离在峰值上会制造新的 hol 阻塞——某一池打满、另一池空。允许临时 colocate，是用短暂的阶段干扰换集群级的可调度性。",-1)),(t(),o(E,null,{default:i(()=>[l(s,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20PR%5B%22Prompt%20%E9%98%B6%E6%AE%B5%22%5D%0A%20%20%20%20PF%5B%22%E6%95%B4%E6%AE%B5%E4%B8%80%E6%AC%A1%E5%89%8D%E5%A1%AB%22%5D%20--%3E%20PF2%5B%22%E5%90%83%20FLOPs%EF%BC%9ATensor%20Core%20%E8%B6%8A%E6%96%B0%E8%B6%8A%E5%80%BC%22%5D%0A%20%20end%0A%20%20subgraph%20GE%5B%22Generation%20%E9%98%B6%E6%AE%B5%22%5D%0A%20%20%20%20GD%5B%22%E6%AF%8F%E6%AD%A5%E5%90%90%E4%B8%80%E4%B8%AA%20token%22%5D%20--%3E%20GD2%5B%22%E5%90%83%E5%B8%A6%E5%AE%BD%E4%B8%8E%20KV%20%E5%AE%B9%E9%87%8F%EF%BC%9A%E7%AE%97%E5%8A%9B%E5%A4%A7%E9%87%8F%E9%97%B2%E7%BD%AE%22%5D%0A%20%20end%0A%20%20PF2%20--%3E%20S%5B%22%E6%8C%89%E9%98%B6%E6%AE%B5%E9%80%89%E6%9C%BA%E5%99%A8%EF%BC%9AP%20%E6%B1%A0%E9%85%8D%E6%96%B0%E5%8D%A1%EF%BC%8CD%20%E6%B1%A0%E9%85%8D%E5%B8%A6%E5%AE%BD%E5%8D%A1%22%5D%0A%20%20GD2%20--%3E%20S%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<p><span class="marginnote">常见误区：把「generation 用旧卡」听成「用任意闲置算力」。D 机仍要装下完整权重、跑同一套核与数值——140 GB 装不下的设备直接出局；能降的只是算力档位与功耗帽，不是模型本身。</span></p><p>状态传输与 DistServe 同类，但动机更偏「机器已经不是同一种」。异构池上 P 卡与 D 卡可能不同代，传输库必须处理设备差异与拓扑。TTFT 统计应包含排队、prompt 执行与跨机拷贝；把拷贝藏进 generation 延迟，异构搜索会往错误的池加卡。</p><h3 id="和-distserve、sarathi-怎么并排读" tabindex="-1">和 DistServe、Sarathi 怎么并排读 <a class="header-anchor" href="#和-distserve、sarathi-怎么并排读" aria-label="Permalink to &quot;和 DistServe、Sarathi 怎么并排读&quot;">​</a></h3><p>三篇都承认两阶段不同，处方不同。Sarathi 留在同一张卡上，用切块与混合批次钉 TBT。DistServe 同构拆实例，用 goodput 搜并行。Splitwise 把拆分延伸到异构与功耗，并用 mixed 池处理突发。生产系统常常三样都要：池间分离、池内切块、突发时 mixed。不要把 ISCA 论文读成「否定切块」，也不要把 OSDI DistServe 读成「否定异构」——它们的实验基线与优化目标本来就不是同一张表。</p><p><span class="marginnote">标题里的 phase splitting 指推理请求的 prompt / generation 两段，不是训练里的流水线阶段，也不是模型并行的 layer split。层间切分可以用来放 KV，但那是放置细节，不是这篇的主声称。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有足够快的机间互连，异构拆分会先死在传输上：便宜的 D 卡若只能走慢 PCIe 域，KV 搬家把 TTFT 吃回去。小模型权重复制的相对成本更高；大模型反正多卡，增量小。Mixed 池若长期变成主路径，系统退化成 colocate，异构收益消失，还多付一层调度。功耗帽是机柜级约束，单卡实验看不出 Splitwise 的主贡献。</p><p>不要把「generation 用更旧的卡」推广成「generation 用任意闲置设备」。权重、精度、核实现必须仍能跑同一模型；不同代卡的数值差还可能改变采样，服务承诺要重新验证。论文数字钉在 Azure 评测时的机器价格与功耗模型上，换一年的目录价，1.4× / 2.35× 都要重算。</p><p>连续批与分页 KV 在拆开之后仍然需要。Splitwise 解决的是阶段与硬件的匹配，不解决单机碎片或前缀复用。长上下文上 KV 体积按提示线性涨，传输税更重，需要与压缩、同节点放置或后续 Mooncake 一类 KV 池一起看。</p><p><span class="marginnote">出处钉 Patel 等 <em>Splitwise: Efficient Generative LLM Inference Using Phase Splitting</em>，ISCA 2024，arXiv:2311.18677。不要给它另编一篇「微软内部 PD 分离」的第二 arXiv；公开可引的就是这一篇。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Splitwise 按 prompt / generation 拆池，并允许异构硬件与 mixed 突发池。</li><li>优化目标显式包含功耗与美元，而不只是 token/s。</li><li>报告约 1.4× 吞吐并降约 20% 成本，或同预算约 2.35× 吞吐。</li><li>表征结论与 DistServe 一致，侧重点是云上的机器代数与电费，而不是 goodput 搜索器。</li><li>互连不够或 mixed 池沦为主路径时，异构拆分失败。</li><li>出处：Patel et al., <em>Splitwise</em>，ISCA 2024，arXiv:2311.18677。</li></ul>',12))])}const T=p(d,[["render",m]]);export{u as __pageData,T as default};
